**What you'd approve: opencode-1's fix** · +17 −1 in src/windows.ts, test/windows.test.ts
```diff
--- a/src/windows.ts
+++ b/src/windows.ts
@@ -3,7 +3,7 @@ export function windows<T>(items: readonly T[], size: number): T[][] {
     throw new RangeError(`size must be a positive integer, got ${size}`);
   }
   const result: T[][] = [];
-  for (let start = 0; start < items.length - size; start++) {
+  for (let start = 0; start <= items.length - size; start++) {
     result.push(items.slice(start, start + size));
   }
   return result;
--- a/test/windows.test.ts
+++ b/test/windows.test.ts
@@ -1,6 +1,22 @@
 import { expect, test } from "bun:test";
 import { windows } from "../src/windows";

+test("keeps the final window that ends on the last item", () => {
+  expect(windows([1, 2, 3], 2)).toEqual([
+    [1, 2],
+    [2, 3],
+  ]);
+  expect(windows([1, 2, 3, 4], 2)).toEqual([
+    [1, 2],
+    [2, 3],
+    [3, 4],
+  ]);
+});
+
+test("returns a single window when the list is exactly the size", () => {
+  expect(windows([1, 2], 2)).toEqual([[1, 2]]);
+});
+
 test("returns no windows when the list is shorter than the size", () => {
   expect(windows([1, 2], 3)).toEqual([]);
 });
```
